    def __init__(self):
        self.root = EmptyNode()

    def lookup(self, key):
        t = LookupTraversal(key)
        self.root = self.root.traverse(t)
        return t.proof()

    def insert(self, key, val):
        t = InsertTraversal(key, val)
        self.root = self.root.traverse(t)
        return t.proof()

    def reset(self):
        self.root = EmptyNode()

